chat_messages_session_generation.value:
"chat_messages"."session_generation" is null or (
                "chat_messages"."session_generation" > 0 and "chat_messages"."author_agent_id" is not null
            )

reminders_script_size.value:
"reminders"."script" is null or (
                octet_length("reminders"."script") between 1 and 16384
            )

triggers_instruction_size.value:
"triggers"."instruction" is null or (
                octet_length("triggers"."instruction") between 1 and 4096
            )
